"use client";

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useCopyToClipboard } from "../hooks/use-copy-to-clipboard";
import { useIsRtl } from "../hooks/use-is-rtl";
import { boxRadiusClassName } from "../lib/style";
import type { DataTableFeatures } from "../lib/table/features";
import { cn } from "@/lib/utils";
import type { RowData, Table } from "@tanstack/react-table";
import { endOfDay, endOfHour, startOfDay, startOfHour } from "date-fns";
import { ClockIcon, CalendarDotsIcon, CalendarDotIcon, CaretLeftIcon, CaretRightIcon, CopyIcon, EqualsIcon, MagnifyingGlassIcon } from "@phosphor-icons/react/ssr";
import type { DataTableFilterField } from "../types";

interface DataTableSheetRowActionProps<
  TData extends RowData,
  TFields extends DataTableFilterField<TData>,
> extends Omit<
    React.ComponentPropsWithRef<typeof DropdownMenuTrigger>,
    "value" | "className"
  > {
  className?: string;
  fieldValue: TFields["value"];
  filterFields: TFields[];
  value: string | number | boolean;
  table: Table<DataTableFeatures, TData>;
}

export function DataTableSheetRowAction<
  TData extends RowData,
  TFields extends DataTableFilterField<TData>,
>({
  fieldValue,
  filterFields,
  value,
  children,
  className,
  table,
  onKeyDown,
  ...props
}: DataTableSheetRowActionProps<TData, TFields>) {
  const { copy, isCopied } = useCopyToClipboard();
  // The menu opens toward the table, which is on the inline-start side.
  const isRtl = useIsRtl();
  const field = filterFields.find((field) => field.value === fieldValue);
  const column = table.getColumn(fieldValue.toString());

  if (!field || !column) return null;

  function renderOptions() {
    if (!field) return null;
    switch (field.type) {
      case "checkbox":
        return (
          <DropdownMenuItem
            onClick={() => {
              // FIXME:
              const filterValue = column?.getFilterValue() as
                | undefined
                | Array<unknown>;
              const newValue = filterValue?.includes(value)
                ? filterValue
                : [...(filterValue || []), value];

              column?.setFilterValue(newValue);
            }}
          >
            <MagnifyingGlassIcon />
            Include
          </DropdownMenuItem>
        );
      case "input":
        return (
          <DropdownMenuItem onClick={() => column?.setFilterValue(value)}>
            <MagnifyingGlassIcon />
            Include
          </DropdownMenuItem>
        );
      case "slider":
        return (
          <DropdownMenuGroup>
            <DropdownMenuItem
              onClick={() => column?.setFilterValue([0, value])}
            >
              {/* FIXME: change icon as it is not clear */}
              <CaretLeftIcon />
              Less or equal than
            </DropdownMenuItem>
            <DropdownMenuItem
              onClick={() => column?.setFilterValue([value, 5000])}
            >
              {/* FIXME: change icon as it is not clear */}
              <CaretRightIcon />
              Greater or equal than
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => column?.setFilterValue([value])}>
              <EqualsIcon />
              EqualsIcon to
            </DropdownMenuItem>
          </DropdownMenuGroup>
        );
      case "timerange":
        const date = new Date(value as string | number);
        return (
          <DropdownMenuGroup>
            <DropdownMenuItem onClick={() => column?.setFilterValue([date])}>
              <CalendarDotIcon />
              Exact timestamp
            </DropdownMenuItem>
            <DropdownMenuItem
              onClick={() => {
                const start = startOfHour(date);
                const end = endOfHour(date);
                column?.setFilterValue([start, end]);
              }}
            >
              <ClockIcon />
              Same hour
            </DropdownMenuItem>
            <DropdownMenuItem
              onClick={() => {
                const start = startOfDay(date);
                const end = endOfDay(date);
                column?.setFilterValue([start, end]);
              }}
            >
              <CalendarDotsIcon />
              Same day
            </DropdownMenuItem>
          </DropdownMenuGroup>
        );
      default:
        return null;
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        className={cn(
          "focus-visible:border-ring focus-visible:ring-ring/50 transition-all outline-none focus-visible:ring-[3px]",
          boxRadiusClassName,
          "relative",
          className,
        )}
        onKeyDown={(e) => {
          if (e.key === "ArrowDown" || e.key === "ArrowUp") {
            // REMINDER: default behavior is to open the dropdown menu
            // But because we use it to navigate between rows, we need to prevent it
            // and only use "Enter" to select the option
            // (Base UI opens on both arrows and stops the event, so skip its
            // handler and let the keydown reach the sheet's row navigation.)
            e.preventBaseUIHandler();
            e.preventDefault();
          }
          onKeyDown?.(e);
        }}
        {...props}
      >
        {children}
        {isCopied ? (
          <div className="bg-background/70 absolute inset-0 place-content-center">
            Value copied
          </div>
        ) : null}
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="start"
        side={isRtl ? "right" : "left"}
        className="w-48"
      >
        {renderOptions()}
        <DropdownMenuSeparator />
        <DropdownMenuItem
          onClick={() => copy(String(value), { timeout: 1000 })}
        >
          <CopyIcon />
          CopyIcon value
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

